import{_ as e,c as r,o as t,a2 as i}from"./chunks/framework.mqLGQ42V.js";const m=JSON.parse('{"title":"层级面板 (Hierarchy) - Rive 编辑器","description":"层级面板显示了文件中的所有对象、资产和视图模型。此视图会根据你选择的画板 (Artboard)、组件 (Component) 或选项卡而变化。 要切换不同的面板，请点击所需的面板。","frontmatter":{"title":"层级面板 (Hierarchy) - Rive 编辑器","description":"层级面板显示了文件中的所有对象、资产和视图模型。此视图会根据你选择的画板 (Artboard)、组件 (Component) 或选项卡而变化。 要切换不同的面板，请点击所需的面板。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 界面面板, 层级面板"}]]},"headers":[],"relativePath":"editor/interface-overview/hierarchy.md","filePath":"editor/interface-overview/hierarchy.md","lastUpdated":1774867914000}'),o={name:"editor/interface-overview/hierarchy.md"};function s(n,a,h,d,l,c){return t(),r("div",null,[...a[0]||(a[0]=[i('<p>界面概览</p><h1 id="层级面板-hierarchy" tabindex="-1">层级面板 (Hierarchy) <a class="header-anchor" href="#层级面板-hierarchy" aria-label="Permalink to &quot;层级面板 (Hierarchy)&quot;">​</a></h1><p>层级面板显示了文件中的所有对象、资产和视图模型。此视图会根据你选择的画板 (Artboard)、组件 (Component) 或选项卡而变化。</p><h1 id="​-切换视图-switching-views" tabindex="-1"><a href="#switching-views">​</a> 切换视图 (Switching Views) <a class="header-anchor" href="#​-切换视图-switching-views" aria-label="Permalink to &quot;[​](#switching-views) 切换视图 (Switching Views)&quot;">​</a></h1><p>要切换不同的面板，请点击所需的面板。 <img src="https://help.rive.app/images/SwitchView.gif" alt="切换视图 Gi"></p><h1 id="​-层级面板-hierarchy" tabindex="-1"><a href="#hierarchy">​</a> 层级面板 (Hierarchy) <a class="header-anchor" href="#​-层级面板-hierarchy" aria-label="Permalink to &quot;[​](#hierarchy) 层级面板 (Hierarchy)&quot;">​</a></h1><p>层级面板是一个树状视图，它既显示了舞台上对象之间的父子关系，也显示了它们的渲染顺序。通过观看视频或阅读下文来了解层级面板。 父子关系是 Rive 的核心概念，它允许你以极小的代价创建复杂的层级式动画。<a href="/docs/editor/fundamentals/groups">分组 (Groups)</a> 和 <a href="/docs/editor/manipulating-shapes/bones">骨骼 (Bones)</a> 在 Rive 中都可以拥有子级。</p><p>层级面板中的每一行代表舞台上的一个项目。在拥有嵌套子级的项目旁边会出现一个带箭头的圆型按钮。此按钮允许你展开和折叠子级列表。</p><h2 id="​-父子关系-parent-child-relationships" tabindex="-1"><a href="#parent-child-relationships">​</a> <strong>父子关系 (Parent-child relationships)</strong> <a class="header-anchor" href="#​-父子关系-parent-child-relationships" aria-label="Permalink to &quot;[​](#parent-child-relationships) **父子关系 (Parent-child relationships)**&quot;">​</a></h2><p>任何类型的对象都可以是另一种类型对象的父级或子级。当一个对象是另一个对象的子级时，它会继承其父级的所有变换。例如，更改父级对象的缩放将影响子级对象。这些变换是相对于父级原点而非局部原点发生的。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 层级父子示例) 这些父子关系的深度是无限的，因此你可以不断堆叠（或嵌套）项目，创建孙级、曾孙级等等。</p></blockquote><h3 id="​-更改父子关系" tabindex="-1"><a href="#change-parent-child-relationships">​</a> <strong>更改父子关系</strong> <a class="header-anchor" href="#​-更改父子关系" aria-label="Permalink to &quot;[​](#change-parent-child-relationships) **更改父子关系**&quot;">​</a></h3><p>要更改对象之间的关系，请将对象拖放进或拖离另一个对象。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 更改关系示例)</p></blockquote><h2 id="​-绘制顺序-draw-order" tabindex="-1"><a href="#draw-order">​</a> <strong>绘制顺序 (Draw Order)</strong> <a class="header-anchor" href="#​-绘制顺序-draw-order" aria-label="Permalink to &quot;[​](#draw-order) **绘制顺序 (Draw Order)**&quot;">​</a></h2><p>除了显示对象之间的关系外，层级面板还显示了文件的绘制顺序（渲染顺序），顶部的对象显示在前面，底部的对象显示在后面。</p><h3 id="​-更改绘制顺序" tabindex="-1"><a href="#change-draw-order">​</a> <strong>更改绘制顺序</strong> <a class="header-anchor" href="#​-更改绘制顺序" aria-label="Permalink to &quot;[​](#change-draw-order) **更改绘制顺序**&quot;">​</a></h3><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 更改绘制顺序示例) 要更改舞台上对象的绘制顺序，请在列表中将形状或分组向上或向下拖到另一个之上或之下。请注意，绘制顺序也会影响对象在布局 (Layout) 中的放置和处理方式。在此处了解更多信息：<a href="/docs/editor/layouts/overview">此处</a>。 绘制顺序可以制作动画，但过程稍微深入一点。请在 <a href="https://help.rive.app/editor/animate-mode/animating-draw-order" target="_blank" rel="noreferrer">绘制顺序动画</a> 页面阅读相关内容。</p></blockquote><h2 id="​-右键菜单-right-click-menu" tabindex="-1"><a href="#right-click-menu">​</a> <strong>右键菜单 (Right Click Menu)</strong> <a class="header-anchor" href="#​-右键菜单-right-click-menu" aria-label="Permalink to &quot;[​](#right-click-menu) **右键菜单 (Right Click Menu)**&quot;">​</a></h2><p>在层级面板中右键点击任何对象都会弹出一个针对不同对象的选项菜单。在菜单中，你可以找到复制/粘贴对象和样式、删除对象、将对象包裹在 <a href="/docs/editor/layouts/overview">布局 (Layouts)</a> 和 <a href="/docs/editor/manipulating-shapes/solos">Solo (Solos)</a> 中、显示依赖图、添加 <a href="/docs/editor/tagging">标签 (Tags)</a>、翻转绘制顺序以及 <a href="/docs/editor/exporting/exporting-for-runtime">导出名称</a> 的功能。 <img src="https://help.rive.app/images/right_click.png" alt="右键菜单 Pn"> 其中许多选项都有快捷键，可以在选项旁边找到，也可以在快捷键菜单中查看。</p><h1 id="​-​资产面板-assets-panel" tabindex="-1"><a href="#​assets-panel">​</a> ​资产面板 (Assets Panel) <a class="header-anchor" href="#​-​资产面板-assets-panel" aria-label="Permalink to &quot;[​](#​assets-panel) ​资产面板 (Assets Panel)&quot;">​</a></h1><p>资产面板是你的图像、Lottie 文件、音频和自定义字体的列表视图。此面板允许你添加、移除、替换和修改文件中添加的所有资产。在下文阅读有关导入和修改资产的更多信息。 <img src="https://help.rive.app/images/Assets.png" alt="资产面板 Pn"></p><h2 id="导入资产-importing-assets" tabindex="-1"><a href="/docs/editor/fundamentals/importing-assets">导入资产 (Importing Assets)</a> <a class="header-anchor" href="#导入资产-importing-assets" aria-label="Permalink to &quot;[导入资产 (Importing Assets)](/editor/fundamentals/importing-assets.md)&quot;">​</a></h2><h2 id="音频事件-audio-events" tabindex="-1"><a href="/docs/editor/events/audio-events">音频事件 (Audio Events)</a> <a class="header-anchor" href="#音频事件-audio-events" aria-label="Permalink to &quot;[音频事件 (Audio Events)](/editor/events/audio-events)&quot;">​</a></h2><h1 id="​-数据面板-data-panel" tabindex="-1"><a href="#data-panel">​</a> 数据面板 (Data Panel) <a class="header-anchor" href="#​-数据面板-data-panel" aria-label="Permalink to &quot;[​](#data-panel) 数据面板 (Data Panel)&quot;">​</a></h1><p>数据面板是创建、组织和查看文件所有视图模型 (View Models)、枚举 (Enums) 和转换器 (Converters) 的地方。该面板分为三个独立空间：视图模型、枚举和转换器。在此处了解更多关于数据绑定 (Data Binding) 的信息：<a href="/docs/editor/data-binding/overview">此处</a>。 <img src="https://help.rive.app/images/Data.png" alt="数据面板 Pn"> 每个部分右侧的加号按钮允许你添加新的视图模型、枚举或转换器。 如果任何部分有相关的元素，可以使用左侧的箭头图标展开或折叠列表。</p>',26)])])}const u=e(o,[["render",s]]);export{m as __pageData,u as default};
